 }

-module.exports = { nowIso };
+async function withRetry(fn, { attempts, baseMs }) {
+  let lastErr;
+  for (let i = 0; i < attempts; i += 1) {
+    try {
+      return await fn();
+    } catch (err) {
+      lastErr = err;
+      if (i === attempts - 1) break;
